import type { Database } from "better-sqlite3";
import { DEFAULT_SETTINGS, type GameSettings, type RunRecordInput, type RunRecord } from "@snake/contracts";

type RunRow = {
  id: string;
  profile_id: string;
  variation_id: string | null;
  score: number;
  duration_ms: number;
  ended_at: string;
};

export const gameQueries = (db: Database) => ({
  getHighScoreByProfileId(profileId: string): number {
    const row = db
      .prepare(
        `SELECT MAX(score) as high_score
         FROM game_runs
         WHERE profile_id = ?`
      )
      .get(profileId) as { high_score: number | null } | undefined;

    return row?.high_score ?? 0;
  },

  listLeaderboard(limit: number, scope: "active" | "global", profileId: string, variationId?: string, gameMode?: "single" | "multiplayer"): Array<{
    rank: number;
    userId: string;
    profileName: string;
    score: number;
    endedAt: string;
    variationName?: string;
    gameMode: "single" | "multiplayer";
    isMultiplayerWin: boolean;
  }> {
    const safeLimit = Math.max(1, limit);

    let query = `
      SELECT r.profile_id, p.name AS profile_name, r.score, r.ended_at, v.name AS variation_name, 
             r.game_mode, r.winner_profile_id
      FROM game_runs r
      JOIN profiles p ON p.id = r.profile_id
      LEFT JOIN game_variations v ON v.id = r.variation_id
    `;

    const conditions: string[] = [];
    const params: any[] = [];

    if (scope === "active") {
      conditions.push("r.profile_id = ?");
      params.push(profileId);
    }

    if (variationId) {
      conditions.push("r.variation_id = ?");
      params.push(variationId);
    }

    if (gameMode) {
      conditions.push("r.game_mode = ?");
      params.push(gameMode);
    }

    if (conditions.length > 0) {
      query += " WHERE " + conditions.join(" AND ");
    }

    query += " ORDER BY r.score DESC, datetime(r.ended_at) DESC LIMIT ?";
    params.push(safeLimit);

    const rows = db.prepare(query).all(...params) as Array<{
      profile_id: string;
      profile_name: string;
      score: number;
      ended_at: string;
      variation_name: string | null;
      game_mode: string;
      winner_profile_id: string | null;
    }>;

    return rows.map((row, index) => ({
      rank: index + 1,
      userId: row.profile_id,
      profileName: row.profile_name,
      score: row.score,
      endedAt: row.ended_at,
      variationName: row.variation_name || undefined,
      gameMode: row.game_mode as "single" | "multiplayer",
      isMultiplayerWin: row.game_mode === "multiplayer" && row.winner_profile_id === row.profile_id
    }));
  },

  saveRun(profileId: string, input: RunRecordInput): RunRecord {
    const id = crypto.randomUUID();
    const createdAt = new Date().toISOString();

    db.prepare(
      `INSERT INTO game_runs (id, profile_id, variation_id, score, duration_ms, ended_at, created_at, game_mode, winner_profile_id, player2_color)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`
    ).run(
      id, 
      profileId, 
      input.variationId || null, 
      input.score, 
      input.durationMs, 
      input.endedAt, 
      createdAt,
      input.gameMode || "single",
      input.winnerProfileId || null,
      input.player2Color || null
    );

    return {
      id,
      userId: profileId,
      score: input.score,
      durationMs: input.durationMs,
      endedAt: input.endedAt,
      variationId: input.variationId,
      gameMode: input.gameMode || "single",
      winnerProfileId: input.winnerProfileId,
      player2Color: input.player2Color
    };
  },

  listRecentRunsByProfileId(profileId: string, limit: number): RunRecord[] {
    const safeLimit = Math.max(1, limit);
    const rows = db
      .prepare(
        `SELECT id, profile_id, variation_id, score, duration_ms, ended_at, game_mode, winner_profile_id, player2_color
         FROM game_runs
         WHERE profile_id = ?
         ORDER BY datetime(ended_at) DESC
         LIMIT ?`
      )
      .all(profileId, safeLimit) as Array<RunRow & { game_mode: string; winner_profile_id: string | null; player2_color: string | null }>;

    return rows.map((row) => ({
      id: row.id,
      userId: row.profile_id,
      score: row.score,
      durationMs: row.duration_ms,
      endedAt: row.ended_at,
      variationId: row.variation_id ?? undefined,
      gameMode: row.game_mode as "single" | "multiplayer",
      winnerProfileId: row.winner_profile_id ?? undefined,
      player2Color: row.player2_color ?? undefined
    }));
  },

  getSettingsByProfileId(profileId: string): GameSettings {
    const row = db
      .prepare(
        `SELECT speed, grid_size, variation_id
         FROM game_settings
         WHERE profile_id = ?`
      )
      .get(profileId) as { speed: number; grid_size: number; variation_id: string | null } | undefined;

    if (!row) return DEFAULT_SETTINGS;

    return {
      speed: row.speed,
      gridSize: row.grid_size,
      variationId: row.variation_id ?? undefined
    };
  },

  saveSettingsByProfileId(profileId: string, settings: GameSettings): GameSettings {
    db.prepare(
      `INSERT INTO game_settings (profile_id, speed, grid_size, variation_id, updated_at)
       VALUES (?, ?, ?, ?, ?)
       ON CONFLICT(profile_id) DO UPDATE SET
         speed = excluded.speed,
         grid_size = excluded.grid_size,
         variation_id = excluded.variation_id,
         updated_at = excluded.updated_at`
    ).run(profileId, settings.speed, settings.gridSize, settings.variationId || null, new Date().toISOString());

    return settings;
  }
});

