  let newActiveEffects = [...state.activeEffects];

  // Emit event for food eaten
  emitGameEvent({ type: "food_eaten", effect, value });

  switch (effect) {
    case "speed_increase":
    case "speed_decrease":
      // Add to permanent effects
      newActiveEffects.push({ effect, value });
      break;

    case "add_blocks":
      // Add blocks immediately to the tail
      for (let i = 0; i < value; i++) {
        const tail = newSnake[newSnake.length - 1];
        if (tail) {
          newSnake = [...newSnake, { ...tail }];
        }
      }
      emitGameEvent({ type: "blocks_added", count: value });
      break;

    case "subtract_blocks":
      // Remove blocks from tail (but keep at least 1)
      const blocksToRemove = Math.min(value, newSnake.length - 1);
      newSnake = newSnake.slice(0, newSnake.length - blocksToRemove);
      emitGameEvent({ type: "blocks_removed", count: blocksToRemove });
      break;

    case "double_points":
      newScore += value;
      emitGameEvent({ type: "score_increased", points: value });
      break;
  }

  const oldSpeed = state.currentSpeed;
  const newSpeed = calculateSpeed(state.baseSpeed, newActiveEffects);

  if (newSpeed !== oldSpeed) {
    emitGameEvent({ type: "speed_changed", newSpeed });
  }

  return {
    ...state,
    snake: newSnake,
    score: newScore,
    activeEffects: newActiveEffects,
    currentSpeed: newSpeed
  };
};

export const stepGame = (
  state: GameState,
  settings: GameSettings,
  powerupTypes: PowerupType[],
  maxConcurrentFoods: number
): GameState => {
  if (state.status !== "running") return state;

  // Single-player logic
  if (state.gameMode === "single") {
    const direction =
      oppositeDirection[state.direction] === state.pendingDirection
        ? state.direction
        : state.pendingDirection;

    const head = state.snake[0];
    if (!head) {
      return { ...state, status: "game-over" };
    }

    const delta = directionDelta[direction];
    const nextHead: Cell = { x: head.x + delta.x, y: head.y + delta.y };

    const bodyWithoutTail = state.snake.slice(0, -1);
    const hitsWall = !isInBounds(nextHead, settings.gridSize);
    const hitsSelf = collidesWithSnake(nextHead, bodyWithoutTail);

    if (hitsWall || hitsSelf) {
      return {
        ...state,
        direction,
        status: "game-over"
      };
    }

    // Check if ate any food
    const eatenFoodIndex = state.foods.findIndex(food => isSameCell(nextHead, food.position));
    const ateFood = eatenFoodIndex !== -1;
    const eatenFood = ateFood ? state.foods[eatenFoodIndex] : null;

    // Update snake (grow if ate food)
    const snake = ateFood
      ? [nextHead, ...state.snake]
      : [nextHead, ...state.snake.slice(0, state.snake.length - 1)];

    // Apply effect if food was eaten
    let newState = {
      ...state,
      snake,
      direction,
      pendingDirection: direction,
      tickCount: state.tickCount + 1
    };

    if (ateFood && eatenFood) {
      newState = applyEffect(newState, eatenFood.effect, eatenFood.value);
    }

    // Update foods
    let newFoods = [...state.foods];
    if (ateFood) {
      // Remove eaten food
      newFoods.splice(eatenFoodIndex, 1);
      // Spawn new food to maintain maxConcurrentFoods
      newFoods.push(placeFood(snake, newFoods, settings.gridSize, powerupTypes));
    }

    return {
      ...newState,
      foods: newFoods
    };
  }

  // Multiplayer logic
  if (!state.player2Snake || !state.player2Direction || !state.player2PendingDirection) {
    return state;
  }

  // Update both players' directions
  const p1Direction =
    oppositeDirection[state.direction] === state.pendingDirection
      ? state.direction
      : state.pendingDirection;

  const p2Direction =
    oppositeDirection[state.player2Direction] === state.player2PendingDirection
      ? state.player2Direction
      : state.player2PendingDirection;

  // Calculate next heads for both players
  const p1Head = state.snake[0];
  const p2Head = state.player2Snake[0];

  if (!p1Head || !p2Head) {
    return { ...state, status: "game-over" };
  }

  const p1NextHead: Cell = { 
    x: p1Head.x + directionDelta[p1Direction].x, 
    y: p1Head.y + directionDelta[p1Direction].y 
  };
  const p2NextHead: Cell = { 
    x: p2Head.x + directionDelta[p2Direction].x, 
    y: p2Head.y + directionDelta[p2Direction].y 
  };

  // Check collisions for both players
  const p1HitsWall = !isInBounds(p1NextHead, settings.gridSize);
  const p2HitsWall = !isInBounds(p2NextHead, settings.gridSize);

  const p1HitsSelf = collidesWithSnake(p1NextHead, state.snake.slice(0, -1));
  const p2HitsSelf = collidesWithSnake(p2NextHead, state.player2Snake.slice(0, -1));

  // Check if players hit each other's bodies
  const p1HitsP2Body = collidesWithSnake(p1NextHead, state.player2Snake);
  const p2HitsP1Body = collidesWithSnake(p2NextHead, state.snake);

  // Check head-to-head collision
  const headToHeadCollision = isSameCell(p1NextHead, p2NextHead);

  // Determine deaths
  const p1Dies = p1HitsWall || p1HitsSelf || p1HitsP2Body || headToHeadCollision;
  const p2Dies = p2HitsWall || p2HitsSelf || p2HitsP1Body || headToHeadCollision;

  // If any player dies, end game
  if (p1Dies || p2Dies) {
    const deadPlayers: ("p1" | "p2")[] = [];
    if (p1Dies) deadPlayers.push("p1");
    if (p2Dies) deadPlayers.push("p2");

    const winner = p1Dies && p2Dies ? "tie" : p1Dies ? "p2" : "p1";

    return {
      ...state,
      direction: p1Direction,
      pendingDirection: p1Direction,
      player2Direction: p2Direction,
      player2PendingDirection: p2Direction,
      status: "game-over",
      deadPlayers,
      winner
    };
  }

  // Both players alive - update snakes
  const p1EatenFoodIndex = state.foods.findIndex(food => isSameCell(p1NextHead, food.position));
  const p2EatenFoodIndex = state.foods.findIndex(food => isSameCell(p2NextHead, food.position));

  const p1AteFood = p1EatenFoodIndex !== -1;
  const p2AteFood = p2EatenFoodIndex !== -1;

  const newP1Snake = p1AteFood
    ? [p1NextHead, ...state.snake]
    : [p1NextHead, ...state.snake.slice(0, state.snake.length - 1)];

  const newP2Snake = p2AteFood
    ? [p2NextHead, ...state.player2Snake]
    : [p2NextHead, ...state.player2Snake.slice(0, state.player2Snake.length - 1)];

  // Update foods
  let newFoods = [...state.foods];
  const minFoods = Math.max(maxConcurrentFoods, 2);

  // Remove eaten foods and spawn new ones
  if (p1AteFood && p2AteFood && p1EatenFoodIndex === p2EatenFoodIndex) {
    // Both ate the same food (rare but possible)
    newFoods.splice(p1EatenFoodIndex, 1);
    newFoods.push(placeFood([...newP1Snake, ...newP2Snake], newFoods, settings.gridSize, powerupTypes));
  } else {
    if (p1AteFood) {
      newFoods.splice(p1EatenFoodIndex, 1);
      newFoods.push(placeFood([...newP1Snake, ...newP2Snake], newFoods, settings.gridSize, powerupTypes));
    }
    if (p2AteFood) {
      // Adjust index if p1 already removed a food
      const adjustedIndex = p1AteFood && p2EatenFoodIndex > p1EatenFoodIndex 
        ? p2EatenFoodIndex - 1 
        : p2EatenFoodIndex;
      newFoods.splice(adjustedIndex, 1);
      newFoods.push(placeFood([...newP1Snake, ...newP2Snake], newFoods, settings.gridSize, powerupTypes));
    }
  }

  // Ensure minimum foods
  while (newFoods.length < minFoods) {
    newFoods.push(placeFood([...newP1Snake, ...newP2Snake], newFoods, settings.gridSize, powerupTypes));
  }

  return {
    ...state,
    snake: newP1Snake,
    player2Snake: newP2Snake,
    direction: p1Direction,
    pendingDirection: p1Direction,
    player2Direction: p2Direction,
    player2PendingDirection: p2Direction,
    foods: newFoods,
    tickCount: state.tickCount + 1
  };
};

