<content>import { Box, Stack, Typography } from "@mui/material";
import { useState } from "react";
import { AppDialogShell } from "../shared/AppDialogShell";
import { ActionButton } from "../shared/ActionButton";
import { approvedIcons } from "../../theme/approvedIcons";
import { gameTokens } from "../../theme/tokens";

// Preset color options for Player 2 (design-system colors)
const PLAYER2_COLOR_OPTIONS = [
  { color: gameTokens.colors.blue, label: "Blue" },
  { color: gameTokens.colors.red, label: "Red" },
  { color: gameTokens.colors.gold, label: "Gold" },
  { color: gameTokens.colors.grey, label: "Grey" },
  { color: "#9b59b6", label: "Purple" }, // Purple (not in gameTokens but design-friendly)
  { color: "#e67e22", label: "Orange" }, // Orange
];

type MultiplayerSetupProps = {
  open: boolean;
  onStart: (player2Color: string) => void;
  onCancel: () => void;
};

export const MultiplayerSetup = ({ open, onStart, onCancel }: MultiplayerSetupProps) => {
  const [selectedColor, setSelectedColor] = useState(gameTokens.colors.blue);

  const handleStart = () => {
    onStart(selectedColor);
  };

  return (
    <AppDialogShell
      open={open}
      onClose={onCancel}
      title="2-Player Setup"
      labelledBy="multiplayer-setup-title"
      describedBy="multiplayer-setup-description"
    >
      <Stack spacing={3}>
        <Box>
          <Typography id="multiplayer-setup-title" variant="h6" gutterBottom>
            2-Player Game Setup
          </Typography>
          <Typography id="multiplayer-setup-description" variant="body2" sx={{ mb: 2 }}>
            Player 1 uses <strong>Arrow Keys</strong>
            <br />
            Player 2 uses <strong>WASD Keys</strong>
          </Typography>
        </Box>

        <Box>
          <Typography variant="body2" gutterBottom sx={{ fontWeight: 600 }}>
            Choose Player 2's Snake Color:
          </Typography>
          <Box
            sx={{
              display: "grid",
              gridTemplateColumns: "repeat(3, 1fr)",
              gap: 1.5,
              mt: 1.5
            }}
          >
            {PLAYER2_COLOR_OPTIONS.map((option) => (
              <Box
                key={option.color}
                onClick={() => setSelectedColor(option.color)}
                sx={{
                  width: "100%",
                  aspectRatio: "1",
                  backgroundColor: option.color,
                  borderRadius: 1,
                  cursor: "pointer",
                  border: "3px solid",
                  borderColor: selectedColor === option.color ? "primary.main" : "transparent",
                  transition: "all 0.2s",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  "&:hover": {
                    transform: "scale(1.05)",
                    borderColor: selectedColor === option.color ? "primary.main" : "action.hover"
                  }
                }}
                role="button"
                tabIndex={0}
                aria-label={`Select ${option.label} color for Player 2`}
                aria-pressed={selectedColor === option.color}
                onKeyDown={(e) => {
                  if (e.key === "Enter" || e.key === " ") {
                    e.preventDefault();
                    setSelectedColor(option.color);
                  }
                }}
              >
                {selectedColor === option.color && (
                  <Box
                    sx={{
                      color: "white",
                      filter: "drop-shadow(0 0 2px rgba(0,0,0,0.5))"
                    }}
                  >
                    <approvedIcons.check />
                  </Box>
                )}
              </Box>
            ))}
          </Box>
          <Typography
            variant="caption"
            sx={{
              display: "block",
              mt: 1,
              textAlign: "center",
              color: (theme) => theme.ui.leaderboard.mutedText
            }}
          >
            Selected: {PLAYER2_COLOR_OPTIONS.find((opt) => opt.color === selectedColor)?.label}
          </Typography>
        </Box>

        <Stack direction="row" spacing={2} sx={{ mt: 2 }}>
          <ActionButton
            tone="neutral"
            icon={<approvedIcons.close />}
            responsiveIconOnly
            onClick={onCancel}
            sx={{ flex: 1 }}
          >
            Cancel
          </ActionButton>
          <ActionButton
            tone="play"
            icon={<approvedIcons.play />}
            responsiveIconOnly
            onClick={handleStart}
            sx={{ flex: 1 }}
          >
            Start Game
          </ActionButton>
        </Stack>
      </Stack>
    </AppDialogShell>
  );
};
