  boardGridColor?: string;
};

const toKey = (cell: Cell): string => `${cell.x}:${cell.y}`;

export const GameBoard = ({
  gridSize,
  gameMode = "single",
  snake,
  player2Snake,
  foods,
  snakeHeadImage,
  boardBackgroundColor,
  snakeColor,
  snakeHeadColor,
  player2Color,
  boardGridColor
}: GameBoardProps) => {
  const theme = useTheme();
  const snakeSet = new Set(snake.map(toKey));
  const head = snake[0];
  const snakeHeadKey = head ? toKey(head) : "";

  const player2SnakeSet = player2Snake ? new Set(player2Snake.map(toKey)) : new Set();
  const player2Head = player2Snake?.[0];
  const player2HeadKey = player2Head ? toKey(player2Head) : "";

  const foodMap = new Map(foods.map((food) => [toKey(food.position), food]));
  const cells = Array.from({ length: gridSize * gridSize }, (_, index) => ({
    x: index % gridSize,
    y: Math.floor(index / gridSize)
  }));

  return (
    <Box sx={{ position: "relative" }}>
      {gameMode === "multiplayer" && (
        <Box
          sx={{
            display: "flex",
            justifyContent: "space-between",
            mb: 1,
            px: 1
          }}
        >
          <Typography variant="caption" sx={{ fontWeight: 600, color: snakeColor || theme.game.snake }}>
            P1 (Arrows)
          </Typography>
          <Typography variant="caption" sx={{ fontWeight: 600, color: player2Color || "#5BB9C2" }}>
            P2 (WASD)
          </Typography>
        </Box>
      )}
      <Box
        sx={{
          display: "grid",
          gridTemplateColumns: `repeat(${gridSize}, minmax(0, 1fr))`,
          width: "min(100%, 720px)",
          aspectRatio: "1 / 1",
          mx: "auto",
          border: "1px solid",
          borderColor: theme.ui.gameBoard.border,
          borderRadius: 1,
          overflow: "hidden",
          backgroundColor: boardBackgroundColor || theme.game.boardBg
        }}
