          const isP1Snake = snakeSet.has(key);
          const isP1Head = key === snakeHeadKey;
          const isP2Snake = player2SnakeSet.has(key);
          const isP2Head = key === player2HeadKey;

          let backgroundColor = "transparent";
          let backgroundImage: string | undefined;

