          } else if (isP1Snake) {
            backgroundColor = snakeColor || theme.game.snake;
          } else if (isP2Head) {
            backgroundColor = player2Color || "#5BB9C2";
          } else if (isP2Snake) {
            backgroundColor = player2Color || "#5BB9C2";
          } else if (isFood) {
